#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

int main() {
    char phone_numbers[10005];
    if (fgets(phone_numbers, sizeof(phone_numbers), stdin) == NULL) {
        return 0;
    }

    size_t len = strlen(phone_numbers);
    if (len > 0 && phone_numbers[len - 1] == '\n') {
        phone_numbers[len - 1] = '\0';
        len--;
    }

    if (len == 0) {
        printf("\n");
        return 0;
    }

    char *result = (char *)malloc((len + 1) * sizeof(char));
    if (result == NULL) {
        return 1;
    }

    int result_idx = 0;
    int i = 0;

    while (i < len) {
        int start = i;
        while (i < len && phone_numbers[i] != ' ') {
            i++;
        }
        int end = i;

        int digit_count = 0;
        for (int j = start; j < end; j++) {
            if (isdigit(phone_numbers[j])) {
                digit_count++;
            }
        }

        int asterisk_count = digit_count - 4;
        int asterisk_printed = 0;

        for (int j = start; j < end; j++) {
            if (isdigit(phone_numbers[j])) {
                if (asterisk_printed < asterisk_count) {
                    result[result_idx++] = '*';
                    asterisk_printed++;
                } else {
                    result[result_idx++] = phone_numbers[j];
                }
            } else {
                result[result_idx++] = phone_numbers[j];
            }
        }

        if (i < len) {
            result[result_idx++] = ' ';
        }
    }

    result[result_idx] = '\0';
    printf("%s\n", result);
    free(result);
    return 0;
}
